icash_next_before_signing:
CREATE OR REPLACE FUNCTION public.icash_next_before_signing()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_live_conversations; t public.icash_automation_tickets;
begin
 select * into c from public.icash_live_conversations where state='waiting' and next_poll_at<=now() and poll_attempts<60 order by next_poll_at for update skip locked limit 1;
 if found then
  update public.icash_live_conversations set poll_attempts=poll_attempts+1,next_poll_at=now()+interval '2 minutes' where id=c.id;
  insert into public.icash_automation_tickets(account_id,kind,live_call_id) values(c.account_id,'voice_result',c.id) returning * into t;
  return jsonb_build_object('token',t.token);
 end if;
 update public.icash_live_conversations set state='review' where state='waiting' and poll_attempts>=60 and next_poll_at<=now();
 return public.icash_next_acquisition();
end $function$

icash_next_before_voice_dispatch:
CREATE OR REPLACE FUNCTION public.icash_next_before_voice_dispatch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e public.icash_signing_envelopes; t public.icash_automation_tickets;
begin
 select * into e from public.icash_signing_envelopes where state in ('awaiting_counterparty','customer_signature_needed') and provider_id is not null and next_poll_at<=now() and created_at>now()-interval '45 days' order by next_poll_at for update skip locked limit 1;
 if found then
  update public.icash_signing_envelopes set next_poll_at=now()+interval '10 minutes' where id=e.id;
  insert into public.icash_automation_tickets(account_id,kind,signing_id) values(e.account_id,'signing_result',e.id) returning * into t;
  return jsonb_build_object('token',t.token);
 end if;
 return public.icash_next_before_signing();
end $function$

icash_next_outreach_channel:
CREATE OR REPLACE FUNCTION public.icash_next_outreach_channel()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare last_voice timestamptz;last_text timestamptz;ticket jsonb;
begin
 perform pg_advisory_xact_lock(726341927);
 select last_dispatch_at into last_voice from public.icash_voice_scheduler where id=1;
 -- Existing (kind,created_at DESC) index keeps this read bounded.
 select created_at into last_text from public.icash_automation_tickets
 where kind='seller_opener' order by created_at desc limit 1;
 -- Give a waiting call its turn after a text. If either lane has no eligible
 -- work, the existing fallback continues through the other work immediately.
 if last_voice is null or last_text>last_voice then
  ticket:=public.icash_issue_ready_voice_ticket();
  if ticket->>'token' is not null then return ticket;end if;
 end if;
 return public.icash_next_before_unstarted_sms_recovery();
end $function$
